-- 0001_initial_schema.sql
--
-- Foundational schema. No rows are inserted: the production registry starts
-- empty (ADR-002) and there is no seed data by design.
--
-- Conventions:
--   * ids are UUID TEXT (generated by the application, not SQLite).
--   * timestamps are UTC ISO-8601 TEXT, e.g. 2026-11-18T02:38:03.398Z.
--   * booleans are INTEGER 0/1 with a CHECK.
--   * JSON columns hold validated, non-secret payloads only.

CREATE TABLE backends (
  id                 TEXT PRIMARY KEY,
  name               TEXT NOT NULL,
  description        TEXT,
  transport          TEXT NOT NULL CHECK (transport IN ('stdio', 'streamable-http')),
  config_json        TEXT NOT NULL,
  enabled            INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  timeout_ms         INTEGER NOT NULL DEFAULT 30000 CHECK (timeout_ms BETWEEN 100 AND 600000),
  concurrency_mode   TEXT NOT NULL DEFAULT 'serialized' CHECK (concurrency_mode IN ('parallel', 'serialized', 'limited')),
  concurrency_limit  INTEGER CHECK (concurrency_limit BETWEEN 1 AND 64),
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  -- Deletion is a tombstone: activity/audit rows keep a valid reference and
  -- "was this backend ever configured?" stays answerable.
  deleted_at         TEXT,
  -- A limit exists if and only if the mode is 'limited'.
  CHECK (concurrency_mode <> 'limited' OR concurrency_limit IS NOT NULL),
  CHECK (concurrency_mode =  'limited' OR concurrency_limit IS NULL)
);

CREATE UNIQUE INDEX idx_backends_name_active ON backends (name) WHERE deleted_at IS NULL;
CREATE INDEX idx_backends_enabled ON backends (enabled) WHERE deleted_at IS NULL;

CREATE TABLE backend_runtime (
  backend_id          TEXT PRIMARY KEY REFERENCES backends (id) ON DELETE CASCADE,
  status              TEXT NOT NULL CHECK (status IN ('disconnected', 'connecting', 'connected', 'unhealthy', 'error', 'disabled')),
  last_connected_at   TEXT,
  last_health_check_at TEXT,
  last_error_code     TEXT,
  last_error_at       TEXT,
  last_error_message  TEXT,
  reconnect_attempts  INTEGER NOT NULL DEFAULT 0 CHECK (reconnect_attempts >= 0),
  updated_at          TEXT NOT NULL
);

CREATE INDEX idx_backend_runtime_status ON backend_runtime (status);

CREATE TABLE agents (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL,
  description   TEXT,
  client_type   TEXT,
  enabled       INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL,
  last_seen_at  TEXT,
  deleted_at    TEXT
);

CREATE UNIQUE INDEX idx_agents_name_active ON agents (name) WHERE deleted_at IS NULL;
CREATE INDEX idx_agents_enabled ON agents (enabled) WHERE deleted_at IS NULL;
CREATE INDEX idx_agents_last_seen ON agents (last_seen_at);

-- Credentials are a separate entity: listing agents can never serialize a verifier.
-- Only a SHA-256 verifier hash is stored; the raw token is never persisted.
CREATE TABLE agent_credentials (
  id                   TEXT PRIMARY KEY,
  agent_id             TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
  credential_hash      TEXT NOT NULL CHECK (length(credential_hash) = 64),
  label                TEXT,
  created_at           TEXT NOT NULL,
  expires_at           TEXT,
  last_used_at         TEXT,
  revoked_at           TEXT
);

CREATE UNIQUE INDEX idx_agent_credentials_hash ON agent_credentials (credential_hash);
CREATE INDEX idx_agent_credentials_agent ON agent_credentials (agent_id, revoked_at);
CREATE INDEX idx_agent_credentials_expiry ON agent_credentials (expires_at);

CREATE TABLE policies (
  id           TEXT PRIMARY KEY,
  name         TEXT NOT NULL,
  description  TEXT,
  priority     INTEGER NOT NULL DEFAULT 0 CHECK (priority BETWEEN -1000 AND 1000),
  rules_json   TEXT NOT NULL,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);

CREATE UNIQUE INDEX idx_policies_name ON policies (name);

CREATE TABLE agent_policy_assignments (
  agent_id    TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
  policy_id   TEXT NOT NULL REFERENCES policies (id) ON DELETE CASCADE,
  created_at  TEXT NOT NULL,
  PRIMARY KEY (agent_id, policy_id)
);

CREATE INDEX idx_assignments_policy ON agent_policy_assignments (policy_id);

CREATE TABLE sessions (
  id                TEXT PRIMARY KEY,
  agent_id          TEXT NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
  created_at        TEXT NOT NULL,
  last_activity_at  TEXT NOT NULL,
  expires_at        TEXT,
  revoked_at        TEXT,
  metadata_json     TEXT
);

CREATE INDEX idx_sessions_agent ON sessions (agent_id);
CREATE INDEX idx_sessions_expiry ON sessions (expires_at);
CREATE INDEX idx_sessions_revoked ON sessions (revoked_at);

-- Operational history. Separate from audit_events: high volume, short retention.
CREATE TABLE activity_events (
  id           TEXT PRIMARY KEY,
  type         TEXT NOT NULL,
  request_id   TEXT,
  agent_id     TEXT REFERENCES agents (id) ON DELETE SET NULL,
  backend_id   TEXT REFERENCES backends (id) ON DELETE SET NULL,
  tool_name    TEXT,
  outcome      TEXT NOT NULL CHECK (outcome IN ('success', 'failure', 'denied')),
  error_code   TEXT,
  duration_ms  INTEGER CHECK (duration_ms >= 0),
  created_at   TEXT NOT NULL
);

CREATE INDEX idx_activity_created ON activity_events (created_at);
CREATE INDEX idx_activity_agent ON activity_events (agent_id, created_at);
CREATE INDEX idx_activity_backend ON activity_events (backend_id, created_at);
CREATE INDEX idx_activity_tool ON activity_events (tool_name, created_at);
CREATE INDEX idx_activity_request ON activity_events (request_id);

-- Administrative and security-sensitive history. Append-only by design: no
-- update or delete path exists in the repository interface.
CREATE TABLE audit_events (
  id           TEXT PRIMARY KEY,
  actor_type   TEXT NOT NULL CHECK (actor_type IN ('admin', 'agent', 'system')),
  actor_id     TEXT,
  action       TEXT NOT NULL,
  target_type  TEXT,
  target_id    TEXT,
  result       TEXT NOT NULL CHECK (result IN ('success', 'failure', 'denied')),
  request_id   TEXT,
  metadata_json TEXT,
  created_at   TEXT NOT NULL
);

CREATE INDEX idx_audit_created ON audit_events (created_at);
CREATE INDEX idx_audit_actor ON audit_events (actor_id, created_at);
CREATE INDEX idx_audit_action ON audit_events (action, created_at);
CREATE INDEX idx_audit_target ON audit_events (target_id, created_at);

-- Dashboard owner accounts. The authentication flow is a later phase; the table
-- exists so credentials are never bolted onto `agents`.
CREATE TABLE admin_users (
  id             TEXT PRIMARY KEY,
  username       TEXT NOT NULL,
  password_hash  TEXT NOT NULL,
  role           TEXT NOT NULL DEFAULT 'owner' CHECK (role IN ('owner', 'admin', 'viewer')),
  enabled        INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL
);

CREATE UNIQUE INDEX idx_admin_users_username ON admin_users (username);

-- Applied migrations. Written by the runner, read on every startup.
CREATE TABLE IF NOT EXISTS schema_migrations (
  version     TEXT PRIMARY KEY,
  checksum    TEXT NOT NULL,
  applied_at  TEXT NOT NULL
);
